fn main(){let p=std::env::args().nth(1).unwrap();let t=std::fs::read_to_string(&p).unwrap();let f=nodecraft_step::StepFile::parse(&t).unwrap();let b=nodecraft_step::read_topology(&f);for s in b.solids.values(){let shell=b.shells.get(&s.shell).unwrap();for fid in &shell.faces{let face=&b.faces[fid];if let Some(e)=f.entities.get(&face.surface){println!("solid {} face {} surface {} {:?}",s.id,fid,e.name,e.args);}}}}
